import sys

s = sys.stdin.read().split()[0]
best = None
n = len(s)
for i in range(n):
    for j in range(i + 1, n + 1):
        v = int(s[i:j])
        if v % 2 == 1 and (best is None or v > best):
            best = v
print(best if best is not None else -1)

